// "AES-256-GCM file vault" round-trip (Node built-in crypto)
const c=require('node:crypto');
const key=c.randomBytes(32),iv=c.randomBytes(12);
const ct=c.createCipheriv('aes-256-gcm',key,iv);
const enc=Buffer.concat([ct.update("quarterly-report-contents",'utf8'),ct.final(),ct.getAuthTag()]);
const tag=enc.slice(-16),data=enc.slice(0,-16);
const dc=c.createDecipheriv('aes-256-gcm',key,iv);dc.setAuthTag(tag);
console.log('decrypted:',Buffer.concat([dc.update(data),dc.final()]).toString());

